namespace icons {
const uint8_t* bits(Icon icon, IconSize size) {
  uint8_t i = static_cast<uint8_t>(icon);
  if (i >= ICON_COUNT) i = static_cast<uint8_t>(Icon::Unknown);
  return kTable[i][size == IconSize::S24 ? 0 : 1];
}
}  // namespace icons
